 "content": "from collections import Counter

def transform(grid):
    """Fill the missing right-hand part of any partial horizontal stripe with 1."""
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for row in out:
        # A partial stripe is a non-background prefix followed by background cells.
        k = 0
        while k < len(row) and row[k] != background:
            k += 1
        if 0 < k < len(row) and all(v == background for v in row[k:]) and len(set(row[:k])) == 1:
            row[k:] = [1] * (len(row) - k)
    return out
